JS = """const payload = JSON_DATA;

function escapeHtml(e){return String(e).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;").replace(/'/g,"&#39;")}
function unpackPayload(e){if(!e)return[];if(e.entries)return e.entries;if(!e.groups)return[];const out=[];e.groups.forEach(g=>{const common=g.common||{};g.items.forEach(it=>{out.push(Object.assign({action:g.action,color:g.color},common,it))})});return out}const dataset=unpackPayload(payload);let filteredData=[...dataset];const hiddenColumns=new Set();function formatBytes(e){if(0===e)return"0 B";let t=parseInt(Math.floor(Math.log(e)/Math.log(1024)));return(e/pow(1024,t)).toFixed(2)+" "+["B","KB","MB","GB","TB"][t]}function pow(e,t){return Math.pow(e,t)}function calculateInsights(e){let t=0,n=0;e.forEach(r=>{let a="number"==typeof r.size?r.size:0;t+=a,r.error!=="-"&&n++}),document.getElementById("insVolume").innerText=formatBytes(t),document.getElementById("insAvgSize").innerText=e.length?formatBytes(t/e.length):"0 B",document.getElementById("insAlerts").innerText=n+" Errors"}function renderTable(e){const t=document.getElementById("tableBody");t.innerHTML="",e.forEach(n=>{const r=document.createElement("tr");const action=escapeHtml(n.action),src=escapeHtml(n.src),dst=escapeHtml(n.dst),date=escapeHtml(n.date),tier=escapeHtml(n.tier),error=escapeHtml(n.error),color=escapeHtml(n.color);r.innerHTML=`<td class="${hiddenColumns.has(0)?"hidden-col":""}"><span class="status-tag" style="color:${color};border-color:${color};background:${color}1a">${action}</span></td><td class="path-cell ${hiddenColumns.has(1)?"hidden-col":""}" style="color:#888">${src}</td><td class="path-cell ${hiddenColumns.has(2)?"hidden-col":""}" style="color:#666">${dst}</td><td style="color:#fff" class="${hiddenColumns.has(3)?"hidden-col":""}">${formatBytes(n.size)}</td><td style="color:#666" class="${hiddenColumns.has(4)?"hidden-col":""}">${date}</td><td style="color:#666" class="${hiddenColumns.has(5)?"hidden-col":""}">${tier}</td><td class="${hiddenColumns.has(6)?"hidden-col":""}" style="color:${n.error==="-"?"#555":"#dc2626"}">${error}</td>`,t.appendChild(r)}),document.getElementById("statCount").innerText=e.length,calculateInsights(e)}function filterData(){let e=document.getElementById("searchInput").value.toLowerCase();filteredData=dataset.filter(t=>Object.values(t).some(n=>n.toString().toLowerCase().includes(e))),renderTable(filteredData)}function applySort(e){const t=["action","src","dst","size","date","tier","error"][e];filteredData.sort((n,r)=>{let a=(n[t]||"").toString().toLowerCase(),o=(r[t]||"").toString().toLowerCase();return"size"===t?n.size-r.size:a.localeCompare(o)}),renderTable(filteredData)}function toggleColumn(e,t){hiddenColumns.has(e)?(hiddenColumns.delete(e),t.classList.add("active"),document.getElementById("th-"+e).classList.remove("hidden-col")):(hiddenColumns.add(e),t.classList.remove("active"),document.getElementById("th-"+e).classList.add("hidden-col")),renderTable(filteredData)}function resetView(){document.getElementById("searchInput").value="",hiddenColumns.clear(),document.querySelectorAll(".toggle-btn").forEach(e=>e.classList.add("active")),document.querySelectorAll("th").forEach(e=>e.classList.remove("hidden-col")),filteredData=[...dataset],renderTable(filteredData)}renderTable(dataset);"""
